'use strict';
const Services8={catalog:{specialist:['Индивидуальный специалист',15000,7,'+3,00 тренировок одному игроку; усталость +4. Заменяет день.'],analyst:['Внешний аналитический штаб',35000,14,'+5,00 разбора пятёрке; усталость +2. Заменяет день.'],hero:['Специалист по герою',12000,7,'+2 практики героя, +0,60 тренировок; усталость +3. Заменяет день.'],draft:['Подготовка драфта',20000,0,'Отчёт через день: баны, пики и сочетания под выбранного соперника.'],psych:['Психологическая сессия',18000,14,'Мораль +3, форма +0,10, усталость +1. Заменяет день пятёрки.'],transfer:['Анализ трансферной сделки',8000,14,'Стоимость первого года, зарплатная нагрузка и три альтернативы.'],audit:['Аудит состава',25000,30,'Через день: две позиции усиления, контракты на 30/60/90 дней и кандидаты.']},
 buy(kind,id,hero,opponent){const cfg=this.catalog[kind],p=S.players[Number(id)],team=S.teams[Number(opponent)],m=Growth8.store();if(!cfg||!trainingAvailable33())return false;const individual=['specialist','hero','transfer'].includes(kind);if(individual&&(!p||p.retired||kind!=='transfer'&&p.team!==S.club))return false;if(kind==='draft'&&(!team||team.id===S.club))return false;
 const key=kind+':'+(individual?p.id:S.club)+(kind==='draft'?':'+team.id+':'+(nextEvent()?.id??0):'');if(m.orders.some(o=>o.key===key&&(cfg[2]?S.day-o.day<cfg[2]:true))){toast('Услуга уже заказана или ещё восстанавливается.');return false;}if(Market7.available()<cfg[1]){toast('Не хватает бюджета с учётом резервов трансферов.');return false;}
 if(kind==='hero'&&(!playerPool4(p).some(h=>h.hero===hero)||(p.heroPractice13[hero]||0)>=20)){toast('Выберите героя из пула с незаполненной практикой.');return false;}if(kind==='specialist'&&p.growth8.training>=100||kind==='analyst'&&roster().every(p=>p.growth8.analysis>=100)){toast('Соответствующая шкала уже заполнена.');return false;}
 const dayWork=['specialist','hero','analyst','psych'].includes(kind);if(dayWork&&Object.values(m.plans).some(plan=>plan.day===S.day+1)){toast('На следующий день уже запланировано занятие.');return false;}
 let text='';if(kind==='transfer'){const q=Market7.quote(p),alts=S.players.filter(a=>!a.retired&&a.team!==S.club&&a.role===p.role&&a.id!==p.id).sort((a,b)=>Math.abs(a.skill-p.skill)-Math.abs(b.skill-p.skill)).slice(0,3);text=p.name+': ориентир первого года '+cash(q.fee+q.salary*52)+', зарплата '+(q.salary/Math.max(1,wage())*100).toFixed(1)+'% от текущих недельных расходов на состав и штаб. Альтернативы: '+alts.map(a=>a.name+' ('+a.skill.toFixed(1)+')').join(', ')+'. Финальные требования определяются переговорами.';}
 if(kind==='audit'){const weakest=roster().slice().sort((a,b)=>a.skill-b.skill).slice(0,2);text=weakest.map(p=>ROLES[p.role]+': '+p.name+'; кандидаты — '+S.players.filter(a=>!a.retired&&a.team!==S.club&&a.role===p.role).sort((a,b)=>b.skill-a.skill).slice(0,3).map(a=>a.name).join(', ')).join('\n')+'\nКонтракты: '+[30,60,90].map(d=>d+' дней — '+owned().filter(p=>p.contract<=d&&!p.retired).map(p=>p.name).join(', ')).join('; ');}
 if(kind==='draft'){const pool=roster(team).flatMap(p=>playerPool4(p).slice(0,3)),rank=pool.slice().sort((a,b)=>(b.games||0)-(a.games||0)),mine=roster().map(p=>playerPool4(p)[0]?.hero).filter(Boolean);text=team.name+': приоритетные баны — '+[...new Set(rank.map(h=>h.hero))].slice(0,3).join(', ')+'; опасные пики — '+[...new Set(rank.map(h=>h.hero))].slice(3,6).join(', ')+'. Два варианта связок: '+mine.slice(0,2).join(' + ')+'; '+mine.slice(2,4).join(' + ')+'. Основание: доступные пулы героев, а не полный архив драфтов. При недостатке наблюдений это ориентир, не гарантия.';}
 money(-cfg[1],'Услуга: '+cfg[0]);m.orders.push({key,kind,day:S.day,club:S.club,price:cfg[1],due:S.day+(kind==='transfer'?0:1),text,delivered:kind==='transfer'});
 if(dayWork){for(const a of individual?[p]:roster())Growth8.plan(a,kind,{hero});trainingDay33();}else{save();render();}return true;
 },
 view(){const players=S.players.filter(p=>!p.retired),own=roster(),orders=S.v8?.orders||[];return '<div class="v8-services"><h1>Услуги клуба</h1><p>Игровой бюджет. Занятия заменяют день; отчёты не мешают подготовке. Начисления проходят коэффициенты развития.</p><div class="v8-grid">'+Object.entries(this.catalog).map(([key,c])=>'<section class="panel"><h2>'+c[0]+'</h2><strong>'+cash(c[1])+'</strong><p>'+c[3]+'</p>'+(['specialist','hero','transfer'].includes(key)?'<select id="v8-player-'+key+'" aria-label="Игрок: '+c[0]+'">'+(key==='transfer'?players:own).map(p=>'<option value="'+p.id+'">'+esc(p.name)+'</option>').join('')+'</select>':'')+(key==='hero'?'<input id="v8-hero" placeholder="Герой из пула, например Axe" aria-label="Герой">':'')+(key==='draft'?'<select id="v8-opponent">'+S.teams.filter(t=>t.id!==S.club).map(t=>'<option value="'+t.id+'">'+esc(t.name)+'</option>').join('')+'</select>':'')+btn('Заказать','Services8.buy(\''+key+'\',document.getElementById(\'v8-player-'+key+'\')?.value,document.getElementById(\'v8-hero\')?.value,document.getElementById(\'v8-opponent\')?.value)',true,!trainingAvailable33())+'</section>').join('')+'</div><h2>Заказы и отчёты</h2>'+orders.filter(o=>o.club===S.club).slice(-15).reverse().map(o=>'<section class="panel"><b>'+this.catalog[o.kind][0]+' · '+esc(date(o.day))+'</b><p>'+esc(o.delivered?o.text||'Занятие проведено. Результат учтён в показателях игроков.':'Готовится к '+date(o.due))+'</p></section>').join('')+'</div>';}
};
const tickBeforeServices8=tick;tick=function(...a){const r=tickBeforeServices8(...a);for(const o of S.v8?.orders||[])if(o.due<=S.day)o.delivered=true;return r;};
PAGES.push(['services8','▣','Услуги клуба']);
